#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_trie_collect_words_helper_buffer_full(void) {
    // Setup: Build a trie with at least one word
    const char *words[] = {"hello"};
    struct trie *root = helper_build_trie(words, 1);
    TEST_ASSERT_NOT_NULL(root);

    // Setup buffer and index to trigger path: *buffer_index >= max_words
    char prefix[100] = {0};
    unsigned prefix_len = 0;
    int max_words = 0;  // Buffer capacity is zero
    int buffer_index = 0;  // Already equals max_words
    char *buffer[1] = {NULL};

    // Test: Call helper with buffer already full
    trie_collect_words_helper(root, prefix, prefix_len, buffer, &buffer_index, max_words);

    // Assertions: buffer_index should remain 0, no words collected
    TEST_ASSERT_EQUAL_INT(0, buffer_index);
    TEST_ASSERT_NULL(buffer[0]);

    // Cleanup
    trie_free(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_trie_collect_words_helper_buffer_full);
    return UNITY_END();
}

