#include "../../../include/ds_trie/header.h"

#define ALPHABET_SIZE 26

struct trie {
    struct trie *children[ALPHABET_SIZE];
    bool end_of_word;
};

// Forward declarations for trie functions (since they're not in header.h)
int trie_contains_string(struct trie *trie, const char *word);
int trie_count_words(struct trie *trie);
int trie_count_nodes(struct trie *trie);
int trie_is_empty(struct trie *trie);
int trie_is_leaf(struct trie *trie);
int trie_get_child_count(struct trie *trie);
int trie_get_prefix_node(struct trie *trie, const char *prefix, struct trie **result);
int trie_collect_words(struct trie *trie, const char *prefix, char **buffer, int max_words);
int trie_contains_all(struct trie *trie, const char **words, int word_count);
int trie_insert_words(struct trie *trie, const char **words, int word_count);
int trie_search(struct trie *trie, char *word, unsigned int word_len, struct trie **result);
int trie_insert(struct trie *trie, char *word, unsigned int word_len);
int trie_new(struct trie **trie);
void trie_print(struct trie *trie, char *prefix, unsigned int prefix_len);
void trie_free(struct trie *trie);
int trie_insert_string(struct trie *trie, const char *word);

void trie_collect_words_helper(struct trie *trie, char prefix[], unsigned prefix_len, char **buffer, int *buffer_index, int max_words)
{
    if (NULL == trie || *buffer_index >= max_words) {
        return;
    }

    if (true == trie->end_of_word) {
        // Allocate and copy word
        buffer[*buffer_index] = malloc(prefix_len + 1);
        if (NULL != buffer[*buffer_index]) {
            memcpy(buffer[*buffer_index], prefix, prefix_len);
            buffer[*buffer_index][prefix_len] = '\0';
            (*buffer_index)++;
        }
    }

    for (int i = 0; i < ALPHABET_SIZE && *buffer_index < max_words; i++) {
        if (NULL == trie->children[i]) {
            continue;
        }
        prefix[prefix_len] = i + 'a';
        trie_collect_words_helper(trie->children[i], prefix, prefix_len + 1,
                                   buffer, buffer_index, max_words);
    }
}

typedef struct stdout_capture {
    char *buffer;
    size_t buffer_size;
    int pipe_read_fd;
    int pipe_write_fd;
    int saved_stdout_fd;
} stdout_capture_t;

// ========== Searched From Pool - Assertion Operations ==========

// Function: capture_stdout_start (from helper pool)
stdout_capture_t *capture_stdout_start(void) {
    stdout_capture_t *cap = malloc(sizeof(stdout_capture_t));
    if (!cap) return NULL;
    cap->buffer = NULL;
    cap->buffer_size = 0;
    /* Create a pipe */
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        free(cap);
        return NULL;
    }
    cap->pipe_read_fd = pipefd[0];
    cap->pipe_write_fd = pipefd[1];
    /* Save original stdout */
    cap->saved_stdout_fd = dup(STDOUT_FILENO);
    if (cap->saved_stdout_fd == -1) {
        close(cap->pipe_read_fd);
        close(cap->pipe_write_fd);
        free(cap);
        return NULL;
    }
    /* Redirect stdout to the pipe write end */
    if (dup2(cap->pipe_write_fd, STDOUT_FILENO) == -1) {
        close(cap->saved_stdout_fd);
        close(cap->pipe_read_fd);
        close(cap->pipe_write_fd);
        free(cap);
        return NULL;
    }
    return cap;
}

// Function: capture_stdout_stop (from helper pool)
char *capture_stdout_stop(stdout_capture_t *cap) {
    if (!cap) return NULL;
    /* Flush stdout to ensure all output is written to pipe */
    fflush(stdout);
    /* Close write end of pipe to signal EOF */
    close(cap->pipe_write_fd);
    /* Restore original stdout */
    dup2(cap->saved_stdout_fd, STDOUT_FILENO);
    close(cap->saved_stdout_fd);
    /* Read captured output from pipe */
    size_t total_read = 0;
    size_t buffer_capacity = 1024;
    char *buffer = malloc(buffer_capacity);
    if (!buffer) {
        close(cap->pipe_read_fd);
        free(cap);
        return NULL;
    }
    ssize_t bytes_read;
    while ((bytes_read = read(cap->pipe_read_fd, buffer + total_read,
                               buffer_capacity - total_read - 1)) > 0) {
        total_read += bytes_read;
        if (total_read >= buffer_capacity - 1) {
            buffer_capacity *= 2;
            char *new_buffer = realloc(buffer, buffer_capacity);
            if (!new_buffer) {
                free(buffer);
                close(cap->pipe_read_fd);
                free(cap);
                return NULL;
            }
            buffer = new_buffer;
        }
    }
    buffer[total_read] = '\0';
    close(cap->pipe_read_fd);
    free(cap);
    return buffer;
}

// Function: assert_stdout_equals (from helper pool)
void assert_stdout_equals(stdout_capture_t *cap, const char *expected) {
    char *actual = capture_stdout_stop(cap);
    if (actual == NULL) {
        fprintf(stderr, "Stdout capture failed
");
        exit(1);
    }
    if (strcmp(actual, expected) != 0) {
        fprintf(stderr, "Stdout assertion failed:
");
        fprintf(stderr, "  Expected: "%s"
", expected);
        fprintf(stderr, "  Actual:   "%s"
", actual);
        free(actual);
        exit(1);
    }
    free(actual);
}

// Function: assert_stdout_contains (from helper pool)
void assert_stdout_contains(stdout_capture_t *cap, const char *expected_substring) {
    char *actual = capture_stdout_stop(cap);
    if (actual == NULL) {
        fprintf(stderr, "Stdout capture failed
");
        exit(1);
    }
    if (strstr(actual, expected_substring) == NULL) {
        fprintf(stderr, "Stdout assertion failed (substring not found):
");
        fprintf(stderr, "  Expected substring: "%s"
", expected_substring);
        fprintf(stderr, "  Actual output:      "%s"
", actual);
        free(actual);
        exit(1);
    }
    free(actual);
}

// Function: assert_stdout_not_empty (from helper pool)
void assert_stdout_not_empty(stdout_capture_t *cap) {
    char *actual = capture_stdout_stop(cap);
    if (actual == NULL) {
        fprintf(stderr, "Stdout capture failed
");
        exit(1);
    }
    if (strlen(actual) == 0) {
        fprintf(stderr, "Stdout assertion failed: output was empty
");
        free(actual);
        exit(1);
    }
    free(actual);
}

// ========== Created - Assertion Operations ==========

// Asserts that a word exists in the trie
void helper_assert_trie_contains(struct trie *trie, const char *word) {
    int result = trie_contains_string(trie, word);
    assert(result == 1);
}

// Asserts that a word does not exist in the trie
void helper_assert_trie_not_contains(struct trie *trie, const char *word) {
    int result = trie_contains_string(trie, word);
    assert(result == 0);
}

// Asserts that the trie contains a specific number of words
void helper_assert_trie_word_count(struct trie *trie, int expected_count) {
    int actual_count = trie_count_words(trie);
    assert(actual_count == expected_count);
}

// Asserts that the trie contains a specific number of nodes
void helper_assert_trie_node_count(struct trie *trie, int expected_count) {
    int actual_count = trie_count_nodes(trie);
    assert(actual_count == expected_count);
}

// Asserts that the trie is empty (contains no words)
void helper_assert_trie_empty(struct trie *trie) {
    int result = trie_is_empty(trie);
    assert(result == 1);
}

// Asserts that the trie is not empty (contains at least one word)
void helper_assert_trie_not_empty(struct trie *trie) {
    int result = trie_is_empty(trie);
    assert(result == 0);
}

// Asserts that a trie node is a leaf (has no children)
void helper_assert_trie_leaf(struct trie *trie) {
    int result = trie_is_leaf(trie);
    assert(result == 1);
}

// Asserts that a trie node is not a leaf (has at least one child)
void helper_assert_trie_not_leaf(struct trie *trie) {
    int result = trie_is_leaf(trie);
    assert(result == 0);
}

// Asserts that a trie node has a specific number of children
void helper_assert_trie_child_count(struct trie *trie, int expected_count) {
    int actual_count = trie_get_child_count(trie);
    assert(actual_count == expected_count);
}

// Asserts that a prefix node exists in the trie and returns a non-null result
void helper_assert_trie_prefix_node(struct trie *trie, const char *prefix) {
    struct trie *result = NULL;
    int ret = trie_get_prefix_node(trie, prefix, &result);
    assert(ret == 0);
    assert(result != NULL);
}

// Asserts that collected words from trie match expected words
void helper_assert_trie_collect_words(struct trie *trie, const char *prefix, const char **expected_words, int expected_count) {
    char **buffer = malloc(expected_count * sizeof(char *));
    int collected_count = trie_collect_words(trie, prefix, buffer, expected_count);
    assert(collected_count == expected_count);
    for (int i = 0; i < expected_count; i++) {
        assert(strcmp(buffer[i], expected_words[i]) == 0);
    }
    for (int i = 0; i < collected_count; i++) {
        free(buffer[i]);
    }
    free(buffer);
}

// Asserts that all words in an array exist in the trie
void helper_assert_trie_contains_all(struct trie *trie, const char **words, int word_count) {
    int result = trie_contains_all(trie, words, word_count);
    assert(result == 1);
}

// Asserts that a specific number of words were inserted from an array
void helper_assert_trie_insert_words(struct trie *trie, const char **words, int word_count, int expected_inserted) {
    int inserted = trie_insert_words(trie, words, word_count);
    assert(inserted == expected_inserted);
}

// Asserts that trie_search returns a specific result code and sets result pointer appropriately
void helper_assert_trie_search_result(struct trie *trie, char *word, unsigned int word_len, int expected_ret, int expected_result_null) {
    struct trie *result = NULL;
    int ret = trie_search(trie, word, word_len, &result);
    assert(ret == expected_ret);
    if (expected_result_null) {
        assert(result == NULL);
    } else {
        assert(result != NULL);
    }
}

// Asserts that trie_insert returns a specific result code
void helper_assert_trie_insert_result(struct trie *trie, char *word, unsigned int word_len, int expected_ret) {
    int ret = trie_insert(trie, word, word_len);
    assert(ret == expected_ret);
}

// Asserts that trie_new returns a specific result code and allocates a non-null trie
void helper_assert_trie_new_result(int expected_ret) {
    struct trie *trie = NULL;
    int ret = trie_new(&trie);
    assert(ret == expected_ret);
    if (expected_ret == 0) {
        assert(trie != NULL);
        free(trie);
    } else {
        assert(trie == NULL);
    }
}

// Asserts that trie_print outputs exactly the expected string
void helper_assert_stdout_equals_trie_print(struct trie *trie, char *prefix, unsigned int prefix_len, const char *expected_output) {
    stdout_capture_t *cap = capture_stdout_start();
    trie_print(trie, prefix, prefix_len);
    assert_stdout_equals(cap, expected_output);
}

// Asserts that trie_print output contains a specific substring
void helper_assert_stdout_contains_trie_print(struct trie *trie, char *prefix, unsigned int prefix_len, const char *expected_substring) {
    stdout_capture_t *cap = capture_stdout_start();
    trie_print(trie, prefix, prefix_len);
    assert_stdout_contains(cap, expected_substring);
}

// Asserts that trie_print produces non-empty output
void helper_assert_stdout_not_empty_trie_print(struct trie *trie, char *prefix, unsigned int prefix_len) {
    stdout_capture_t *cap = capture_stdout_start();
    trie_print(trie, prefix, prefix_len);
    assert_stdout_not_empty(cap);
}

// ========== Created - Utility Operations ==========

// Builds a trie from an array of words
struct trie* helper_build_trie(const char **words, int word_count) {
    struct trie *root = NULL;
    if (trie_new(&root) != 0) {
        return NULL;
    }
    for (int i = 0; i < word_count; i++) {
        trie_insert_string(root, words[i]);
    }
    return root;
}

